package com.chat.server

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import io.ktor.server.sessions.*
import io.ktor.server.auth.*
import io.ktor.http.*
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import kotlinx.coroutines.sync.*
import java.util.concurrent.ConcurrentHashMap
import java.security.SecureRandom
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class ChatSession(val userId: String, val token: String, val createdAt: Long)
data class ConnectionState(val session: ChatSession, var authenticated: Boolean = false)

class TokenValidator {
    private val serverSecret = SecureRandom().generateSeed(32)
    private val activeSessions = ConcurrentHashMap<String, ChatSession>()

    fun generateToken(userId: String): String {
        require(!userId.contains(":")) { "Invalid userId" }
        val timestamp = System.currentTimeMillis()
        val payload = "$userId:$timestamp"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(serverSecret, "HmacSHA256"))
        val signature = Base64.getUrlEncoder().encodeToString(mac.doFinal(payload.toByteArray()))
        val token = Base64.getUrlEncoder().encodeToString(payload.toByteArray()) + "." + signature
        activeSessions[userId] = ChatSession(userId, token, timestamp)
        return token
    }

    fun validateToken(token: String): ChatSession? {
        val parts = token.split(".")
        if (parts.size != 2) return null
        val payload = try {
            String(Base64.getUrlDecoder().decode(parts[0]))
        } catch (_: Exception) {
            return null
        }
        val providedSig = parts[1]
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(serverSecret, "HmacSHA256"))
        val expectedSig = Base64.getUrlEncoder().encodeToString(mac.doFinal(payload.toByteArray()))
        if (!constantTimeEquals(expectedSig, providedSig)) return null
        val payloadParts = payload.split(":")
        if (payloadParts.size != 2) return null
        val userId = payloadParts[0]
        val timestamp = payloadParts[1].toLongOrNull() ?: return null
        val session = activeSessions[userId] ?: return null
        if (System.currentTimeMillis() - timestamp > 3600000) return null
        return session
    }

    private fun constantTimeEquals(a: String, b: String): Boolean {
        if (a.length != b.length) return false
        var result = 0
        for (i in a.indices) { result = result or (a[i].code xor b[i].code) }
        return result == 0
    }
}

class ChatRoom(private val validator: TokenValidator) {
    private val connections = ConcurrentHashMap<String, WebSocketSession>()
    private val connectionStates = ConcurrentHashMap<String, ConnectionState>()
    private val broadcastChannel = Channel<Pair<String, String>>(Channel.BUFFERED)
    private val stateMutex = Mutex()

    suspend fun handleConnection(ws: WebSocketSession, initialOrigin: String?) {
        val connId = java.util.UUID.randomUUID().toString()
        connections[connId] = ws

        try {
            for (frame in ws.incoming) {
                when (frame) {
                    is Frame.Text -> handleMessage(connId, frame.readText(), ws, initialOrigin)
                    else -> {}
                }
            }
        } finally {
            connections.remove(connId)
            connectionStates.remove(connId)
        }
    }

    private suspend fun handleMessage(connId: String, raw: String, ws: WebSocketSession, origin: String?) {
        val parts = raw.split("|", limit = 3)
        if (parts.size < 2) return

        when (parts[0]) {
            "AUTH" -> handleAuth(connId, parts[1], ws, origin)
            "MSG" -> handleChatMessage(connId, if (parts.size == 3) parts[2] else parts[1])
            "PING" -> ws.send(Frame.Text("PONG"))
        }
    }

    private suspend fun handleAuth(connId: String, token: String, ws: WebSocketSession, origin: String?) {
        val session = validator.validateToken(token)
        if (session == null) {
            ws.send(Frame.Text("AUTH_FAILED"))
            ws.close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Invalid token"))
            return
        }

        // Origin validation for WebSocket hijacking prevention
        val validatedOrigin = validateOrigin(origin, session)

        if (!validatedOrigin) {
            ws.send(Frame.Text("AUTH_FAILED|ORIGIN_REJECTED"))
            ws.close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Invalid origin"))
            return
        }

        stateMutex.withLock {
            connectionStates[connId] = ConnectionState(session, authenticated = true)
        }

        ws.send(Frame.Text("AUTH_OK|${session.userId}"))
    }

    private fun validateOrigin(origin: String?, session: ChatSession): Boolean {
        val allowedOrigins = listOf(
            "https://chat.example.com",
            "https://app.example.com",
            "https://internal.example.com"
        )
        if (origin == null) return false
        return allowedOrigins.any { allowed -> origin == allowed }
    }

    private suspend fun handleChatMessage(connId: String, message: String) {
        val state = connectionStates[connId] ?: return
        if (!state.authenticated) return

        val sanitized = message.replace("<", "&lt;").replace(">", "&gt;")
        val broadcast = "MSG|${state.session.userId}|$sanitized"

        connections.values.forEach { session ->
            try { session.send(Frame.Text(broadcast)) } catch (_: Exception) {}
        }
    }

    fun startBroadcastWorker() = CoroutineScope(Dispatchers.Default).launch {
        for ((userId, msg) in broadcastChannel) {
            connections.values.forEach { session ->
                try { session.send(Frame.Text("MSG|$userId|$msg")) } catch (_: Exception) {}
            }
        }
    }
}

fun main() {
    val validator = TokenValidator()
    val chatRoom = ChatRoom(validator)
    chatRoom.startBroadcastWorker()

    embeddedServer(Netty, port = 8080) {
        install(WebSockets)
        routing {
            webSocket("/chat") {
                val origin = call.request.headers["Origin"]
                chatRoom.handleConnection(this, origin)
            }
        }
    }.start(wait = true)
}
